set-variable.value:
@{
    try {
      if (!context.Variables.ContainsKey("byokCallerAuthenticated") || !(bool)context.Variables["byokCallerAuthenticated"]
          || !context.Variables.ContainsKey("byokResponseReference")
          || !context.Variables.ContainsKey("byokResponseBackendUrl")) { return ""; }
      var reference = (string)context.Variables["byokResponseReference"];
      if (!System.Text.RegularExpressions.Regex.IsMatch(reference, @"\Aresp_[A-Za-z0-9_-]{1,128}\z")) { return ""; }
      var configured = Newtonsoft.Json.Linq.JArray.Parse((string)context.Variables["byokResponseBackendOrigins"]);
      var backendText = (string)context.Variables["byokResponseBackendUrl"];
        var backend = new Uri(backendText);
        if (backend.Scheme != "https" || backend.Port != 443
          || !string.IsNullOrEmpty(backend.UserInfo) || !string.IsNullOrEmpty(backend.Query) || !string.IsNullOrEmpty(backend.Fragment)) { return ""; }
        var origin = backend.Scheme + "://" + backend.Authority;
      if (!configured.Any(entry => entry.Type == Newtonsoft.Json.Linq.JTokenType.String && string.Equals((string)entry, origin, StringComparison.OrdinalIgnoreCase))) { return ""; }
      return origin + "/openai/v1/responses/" + Uri.EscapeDataString(reference);
    } catch { return ""; }
  }

@{
    var previousFailure = context.Variables.ContainsKey("byokResponseLookupFailed") && (bool)context.Variables["byokResponseLookupFailed"];
    var response = context.Variables.ContainsKey("byokResponseOwnerLookup") ? (IResponse)context.Variables["byokResponseOwnerLookup"] : null;
    return previousFailure || response == null || (response.StatusCode != 200 && response.StatusCode != 404);
  }

@{
    try {
      var response = context.Variables.ContainsKey("byokResponseOwnerLookup") ? (IResponse)context.Variables["byokResponseOwnerLookup"] : null;
      if (response == null || response.StatusCode != 200) { return ""; }
      var document = response.Body.As<Newtonsoft.Json.Linq.JObject>(preserveContent: false);
      return new Newtonsoft.Json.Linq.JObject(
        new Newtonsoft.Json.Linq.JProperty("id", document["id"]),
        new Newtonsoft.Json.Linq.JProperty("object", document["object"]),
        new Newtonsoft.Json.Linq.JProperty("metadata", document["metadata"])
      ).ToString(Newtonsoft.Json.Formatting.None);
    } catch { return ""; }
  }
